html:
{#- ==========================================================================
    MASTER TOUCH MANUFACTURING - PRODUCTION LOG
    DocType : Conversion Entry   |   One page per line of the Items table

    Log type is detected per line from the item groups (and, as a backstop,
    the item codes/names) of the source and finished good. Matching is by
    keyword and is case insensitive, so "Tier 1", "Tier 3", "Primes",
    "Subprimes", "Raw Rosin" etc. all route without being listed one by one.
    ========================================================================== -#}

{%- set LICENSE_NAME = "MASTER TOUCH MANUFACTURING" -%}
{%- set LICENSE_NO   = "DCC-10004754" -%}

{#- ---- staff: login -> printed name and initials -------------------------- -#}
{%- set STAFF = {
    "manufacturing@motleyterpz.com": {"name": "Tori Sutliff", "initials": "TS"},
    "fulfilment@motleyterpz.com":    {"name": "Wolf Stone",   "initials": "WS"}
} -%}

{#- ---- keyword sets (lowercase) ------------------------------------------- -#}
{%- set K_FROZEN = ["fresh frozen", "frozen", "fresh-frozen", "ff "] -%}
{%- set K_ROSIN  = ["rosin", "tier", "prime", "subprime", "full spec", "food grade", "t1", "t2", "t3", "static", "bubble"] -%}
{%- set K_VRR    = ["vrr", "vape ready"] -%}
{%- set K_VAPE   = ["vape", "hardware", "cart", "o2", "packaged"] -%}
{%- set K_GUMMY  = ["gumm"] -%}

{#- ---- log definitions ---------------------------------------------------- -#}
{%- set LOGS = {
  "FROZEN": {
     "title": "FROZEN BIO TO ROSIN",
     "equipment": "Acsess Rosin Wash Machine/ Blue Apline Freeze Dryers/Low Temp Rosin Press",
     "expected": "3.00%", "actual_label": "Actual Yield (Grams)", "uom": "Grams", "rm_note": ""
  },
  "ROSIN_VRR": {
     "title": "ROSIN TO VRR (VAPE READY ROSIN)",
     "equipment": "Across International Vacuum Oven/ 16Oz Wide Mouth Ball Jar",
     "expected": "90.00%", "actual_label": "Actual Yield (Grams and %)", "uom": "Grams", "rm_note": "Item On Back"
  },
  "VAPES": {
     "title": "VRR TO VAPES",
     "equipment": "Thompson Duke Semi Auto Cartridge Dispenser/ 16 oz Wide Mouth Jar/ Across International Vacuum Oven/Titan Air Compressor",
     "expected": "95.00%", "actual_label": "Actual Yield (EACH)", "uom": "Grams", "rm_note": ""
  },
  "BLEND": {
     "title": "BLENDING ROSIN TO MAKE NEW ITEM",
     "equipment": "16 oz Ball Jars or Apropriate Glass Jar/Stainless Steel Lab Untensil",
     "expected": "90.00%", "actual_label": "Actual Yield (Grams and %)", "uom": "Grams", "rm_note": "Item On Back"
  },
  "GUMMIES": {
     "title": "GUMMIES",
     "equipment": "Thompson Duke Semi Auto Cartridge Dispenser/ 16 oz Wide Mouth Jar/ Across International Vacuum Oven/Titan Air Compressor",
     "expected": "95.00%", "actual_label": "Actual Yield (EACH)", "uom": "Grams", "rm_note": ""
  },
  "GENERIC": {
     "title": "PRODUCTION LOG",
     "equipment": "", "expected": "", "actual_label": "Actual Yield", "uom": "Grams", "rm_note": ""
  }
} -%}

{%- set gv = frappe.db.get_value -%}

{#- ---- who submitted ------------------------------------------------------ -#}
{%- set sub_user = doc.modified_by if doc.docstatus == 1 else doc.owner -%}
{%- set sub_full = gv("User", sub_user, "full_name") or sub_user -%}
{%- set sub_name = STAFF[sub_user]["name"] if sub_user in STAFF else sub_full -%}
{%- set sub_init = STAFF[sub_user]["initials"] if sub_user in STAFF else (sub_name.split() | map("first") | join | upper) -%}
{%- set sub_time = frappe.utils.format_datetime(doc.modified, "MM/dd/yyyy HH:mm") -%}
{%- set entry_time = frappe.utils.format_datetime(doc.creation, "hh:mm a") -%}

{%- macro iname(code) -%}
{%- if code -%}{{ gv("Item", code, "item_name") or code }}{%- endif -%}
{%- endmacro -%}

<style>
  .pl { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; color:#000; font-size:8.5pt; line-height:1.25; }
  .pl * { box-sizing:border-box; color:#000; }
  .pl-page { page-break-after: always; }
  .pl-page:last-child { page-break-after: auto; }

  .pl-head { display:flex; justify-content:space-between; align-items:flex-end;
             border-bottom:2px solid #000; padding-bottom:4px; margin-bottom:8px; }
  .pl-lic { font-size:9pt; letter-spacing:.14em; text-transform:uppercase; }
  .pl-title { font-size:14pt; font-weight:700; letter-spacing:.04em; margin-top:2px; }
  .pl-ref { text-align:right; font-size:8pt; line-height:1.5; }
  .pl-ref b { font-size:10pt; }

  .pl-bar { border-top:1.5px solid #000; border-bottom:1px solid #000;
            font-size:7.5pt; font-weight:700; letter-spacing:.16em;
            text-transform:uppercase; padding:3px 2px; margin:9px 0 0; }

  table.pl-t { width:100%; border-collapse:collapse; table-layout:fixed; }
  table.pl-t th, table.pl-t td { border:1px solid #000; padding:3px 5px; vertical-align:top; word-wrap:break-word; }
  table.pl-t th { font-size:7pt; letter-spacing:.08em; text-transform:uppercase; text-align:left; font-weight:700; }
  .pl-lbl { font-size:7pt; letter-spacing:.06em; text-transform:uppercase; font-weight:700; }
  .pl-val { font-size:9pt; }
  .pl-mono { font-family:"Courier New", monospace; font-size:9pt; }
  .pl-eq { height:64px; font-size:9.5pt; font-weight:700; }
  .pl-note { font-size:7pt; font-weight:400; }
  .pl-fill { height:20px; }
  .pl-fill-tall { height:26px; }
  .pl-c { text-align:center; }
  .pl-r { text-align:right; }
  .pl-tot { font-weight:700; }
  .pl-foot { margin-top:10px; border-top:1px solid #000; padding-top:4px;
             display:flex; justify-content:space-between; font-size:7pt; }
</style>

<div class="pl">
{%- for row in doc.items %}

  {%- set rms = [
      {"code": row.raw_material_1, "qty": row.qty_rm_1, "grp": row.rm_1_item_group or (gv("Item", row.raw_material_1, "item_group") if row.raw_material_1 else "")},
      {"code": row.raw_material_2, "qty": row.qty_rm_2, "grp": row.rm_2_item_group or (gv("Item", row.raw_material_2, "item_group") if row.raw_material_2 else "")},
      {"code": row.raw_material_3, "qty": row.qty_rm_3, "grp": row.rm_3_item_group or (gv("Item", row.raw_material_3, "item_group") if row.raw_material_3 else "")},
      {"code": row.raw_material_4, "qty": row.qty_rm_4, "grp": row.rm_4_item_group or (gv("Item", row.raw_material_4, "item_group") if row.raw_material_4 else "")},
      {"code": row.raw_material_5, "qty": row.qty_rm_5, "grp": row.rm_5_item_group or (gv("Item", row.raw_material_5, "item_group") if row.raw_material_5 else "")},
      {"code": row.raw_material_6, "qty": row.qty_rm_6, "grp": row.rm_6_item_group or (gv("Item", row.raw_material_6, "item_group") if row.raw_material_6 else "")},
      {"code": row.raw_material_7, "qty": row.qty_rm_7, "grp": row.rm_7_item_group or (gv("Item", row.raw_material_7, "item_group") if row.raw_material_7 else "")}
  ] -%}
  {%- set fgs = [
      {"code": row.finished_good_1, "qty": row.qty_fg_1, "grp": row.fg_1_item_group or (gv("Item", row.finished_good_1, "item_group") if row.finished_good_1 else "")},
      {"code": row.finished_good_2, "qty": row.qty_fg_2, "grp": row.fg_2_item_group or (gv("Item", row.finished_good_2, "item_group") if row.finished_good_2 else "")}
  ] -%}
  {%- set rm_used = rms | selectattr("code") | list -%}
  {%- set fg_used = fgs | selectattr("code") | list -%}
  {%- set total_rm = rm_used | sum(attribute="qty") -%}
  {%- set total_fg = fg_used | sum(attribute="qty") -%}

  {#- ---- route this line ---- -#}
  {%- set ns = namespace(sf=false, sr=false, sv=false, fr=false, fv=false, fp=false, fgum=false, seen_src="", seen_fg="") -%}

  {%- for x in rm_used -%}
    {%- set hay = ((x.grp or "") ~ " " ~ (x.code or "") ~ " " ~ (gv("Item", x.code, "item_name") or "")) | lower -%}
    {%- set ns.seen_src = ns.seen_src ~ (", " if ns.seen_src else "") ~ (x.grp or x.code) -%}
    {%- for k in K_VRR    if k in hay %}{% set ns.sv = true %}{% endfor -%}
    {%- for k in K_FROZEN if k in hay %}{% set ns.sf = true %}{% endfor -%}
    {%- for k in K_ROSIN  if k in hay %}{% set ns.sr = true %}{% endfor -%}
  {%- endfor -%}

  {%- for x in fg_used -%}
    {%- set hay = ((x.grp or "") ~ " " ~ (x.code or "") ~ " " ~ (gv("Item", x.code, "item_name") or "")) | lower -%}
    {%- set ns.seen_fg = ns.seen_fg ~ (", " if ns.seen_fg else "") ~ (x.grp or x.code) -%}
    {%- for k in K_GUMMY  if k in hay %}{% set ns.fgum = true %}{% endfor -%}
    {%- for k in K_VRR    if k in hay %}{% set ns.fv = true %}{% endfor -%}
    {%- for k in K_VAPE   if k in hay %}{% set ns.fp = true %}{% endfor -%}
    {%- for k in K_ROSIN  if k in hay %}{% set ns.fr = true %}{% endfor -%}
  {%- endfor -%}

  {#- VRR wins over the generic rosin flag on the same item -#}
  {%- if ns.sv %}{% set ns.sr = false %}{% endif -%}
  {%- if ns.fv %}{% set ns.fr = false %}{% endif -%}
  {%- if ns.fgum %}{% set ns.fp = false %}{% endif -%}

  {%- if ns.fgum %}{% set key = "GUMMIES" %}
  {%- elif ns.sf and (ns.fr or ns.fv) %}{% set key = "FROZEN" %}
  {%- elif ns.sv and ns.fp %}{% set key = "VAPES" %}
  {%- elif (ns.sr or ns.sv) and ns.fv %}{% set key = "ROSIN_VRR" %}
  {%- elif ns.sr and ns.fr %}{% set key = "BLEND" %}
  {%- else %}{% set key = "GENERIC" %}
  {%- endif -%}
  {%- set cfg = LOGS[key] -%}

  <div class="pl-page">

    <div class="pl-head">
      <div>
        <div class="pl-lic">{{ LICENSE_NAME }}</div>
        <div class="pl-title">{{ cfg["title"] }}</div>
      </div>
      <div class="pl-ref">
        <b>{{ doc.name }} &nbsp;/&nbsp; LINE {{ loop.index }}</b><br>
        Page {{ loop.index }} of {{ doc.items | length }}<br>
        License No. <span class="pl-mono">{{ LICENSE_NO }}</span>
      </div>
    </div>

    <!-- BATCH IDENTIFICATION -->
    <table class="pl-t">
      <colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup>
      <tr>
        <td class="pl-lbl">Production Date</td>
        <td class="pl-val pl-mono">{{ frappe.format_date(doc.posting_date) }}</td>
        <td class="pl-lbl">Production Time</td>
        <td class="pl-val pl-mono">{{ entry_time }}</td>
      </tr>
      <tr>
        <td class="pl-lbl">Batch ID</td>
        <td class="pl-fill"></td>
        <td class="pl-lbl">Manufactured By</td>
        <td class="pl-fill"></td>
      </tr>
      <tr>
        <td class="pl-lbl">License Number</td>
        <td class="pl-val pl-mono">{{ LICENSE_NO }}</td>
        <td class="pl-lbl">New Metrc UID</td>
        <td class="pl-fill"></td>
      </tr>
    </table>

    <!-- EQUIPMENT -->
    <div class="pl-bar">Equipment &amp; Sanitation</div>
    <table class="pl-t">
      <colgroup><col style="width:58%"><col style="width:27%"><col style="width:15%"></colgroup>
      <tr><th>Equipment</th><th>Date / Time of Sanitation</th><th class="pl-c">Initial</th></tr>
      <tr>
        <td class="pl-eq">
          {{ cfg["equipment"] }}
          {%- if key == "GENERIC" %}
          <div class="pl-note">No log type matched. Source: {{ ns.seen_src }} &nbsp;|&nbsp; Finished good: {{ ns.seen_fg }}</div>
          {%- endif %}
        </td>
        <td></td><td></td>
      </tr>
      <tr><td class="pl-fill-tall"></td><td></td><td></td></tr>
    </table>

    <!-- CANNABIS SOURCE -->
    <div class="pl-bar">Cannabis Source</div>
    <table class="pl-t">
      <colgroup><col style="width:16%"><col style="width:24%"><col style="width:32%"><col style="width:16%"><col style="width:12%"></colgroup>
      <tr>
        <th>Type</th><th>Metrc UID</th><th>Batch Info</th>
        <th class="pl-r">Amount Used (Grams)</th><th class="pl-c">Initial</th>
      </tr>
      {%- for rm in rm_used %}
      <tr>
        <td>{{ rm.grp or "" }}</td>
        <td class="pl-fill"></td>
        <td><span class="pl-mono">{{ rm.code }}</span> &nbsp; {{ iname(rm.code) }}</td>
        <td class="pl-r pl-mono">{{ "%.2f"|format(rm.qty or 0) }}</td>
        <td class="pl-c">{{ sub_init }}</td>
      </tr>
      {%- endfor %}
      {%- for i in range(2) %}
      <tr><td class="pl-fill"></td><td></td><td></td><td></td><td></td></tr>
      {%- endfor %}
      <tr class="pl-tot">
        <td colspan="3" class="pl-r">Total Cannabis Input</td>
        <td class="pl-r pl-mono">{{ "%.2f"|format(total_rm) }}</td>
        <td></td>
      </tr>
    </table>

    <!-- RAW INGREDIENTS -->
    <div class="pl-bar">Raw Ingredients</div>
    <table class="pl-t">
      <colgroup><col style="width:26%"><col style="width:16%"><col style="width:14%"><col style="width:32%"><col style="width:12%"></colgroup>
      <tr><th>Ingredient</th><th class="pl-r">Amount</th><th>UOM</th><th>Lot Number</th><th class="pl-c">Initial</th></tr>
      <tr><td class="pl-fill">{{ cfg["rm_note"] }}</td><td></td><td>Grams</td><td></td><td></td></tr>
      <tr><td class="pl-fill"></td><td></td><td></td><td>N/A</td><td></td></tr>
      <tr><td class="pl-fill"></td><td></td><td></td><td>N/A</td><td></td></tr>
    </table>

    <!-- FINISHED GOOD -->
    <div class="pl-bar">Finished Good</div>
    <table class="pl-t">
      <colgroup><col style="width:16%"><col style="width:24%"><col style="width:32%"><col style="width:16%"><col style="width:12%"></colgroup>
      <tr>
        <th>Type</th><th>New Metrc UID</th><th>Batch Info</th>
        <th class="pl-r">Qty Produced</th><th class="pl-c">Initial</th>
      </tr>
      {%- for fg in fg_used %}
      <tr>
        <td>{{ fg.grp or "" }}</td>
        <td class="pl-fill"></td>
        <td><span class="pl-mono">{{ fg.code }}</span> &nbsp; {{ iname(fg.code) }}</td>
        <td class="pl-r pl-mono">{{ "%.2f"|format(fg.qty or 0) }}</td>
        <td class="pl-c">{{ sub_init }}</td>
      </tr>
      {%- endfor %}
      <tr class="pl-tot">
        <td colspan="3" class="pl-r">Total Finished Good</td>
        <td class="pl-r pl-mono">{{ "%.2f"|format(total_fg) }}</td>
        <td></td>
      </tr>
    </table>

    <!-- YIELD -->
    <div class="pl-bar">Yield</div>
    <table class="pl-t">
      <colgroup><col style="width:22%"><col style="width:28%"><col style="width:16%"><col style="width:34%"></colgroup>
      <tr><th>Expected Yield</th><th>{{ cfg["actual_label"] }}</th><th>UOM</th><th class="pl-c">Initial</th></tr>
      <tr>
        <td class="pl-mono">{{ cfg["expected"] }}</td>
        <td class="pl-fill-tall"></td>
        <td>{{ cfg["uom"] }}</td>
        <td></td>
      </tr>
      <tr>
        <td class="pl-lbl">Deviations / Notes</td>
        <td colspan="3" class="pl-fill-tall"></td>
      </tr>
    </table>

    <!-- QC -->
    <div class="pl-bar">QC Check</div>
    <table class="pl-t">
      <colgroup><col style="width:34%"><col style="width:22%"><col style="width:22%"><col style="width:22%"></colgroup>
      <tr><th>Name</th><th>Date</th><th>Time</th><th class="pl-c">Initial</th></tr>
      <tr><td class="pl-fill-tall"></td><td></td><td></td><td></td></tr>
      <tr><td class="pl-fill-tall"></td><td></td><td></td><td></td></tr>
    </table>

    <div class="pl-foot">
      <div>{{ LICENSE_NAME }} &nbsp;&bull;&nbsp; {{ LICENSE_NO }} &nbsp;&bull;&nbsp; {{ doc.name }} line {{ loop.index }} of {{ doc.items | length }}</div>
      <div>Submitted by {{ sub_name }} ({{ sub_init }}) on {{ sub_time }}</div>
    </div>

  </div>
{%- endfor %}
</div>
